<?php require_once __DIR__.'/auth.php';$user=require_role('supervisor');$carros=db()->query('SELECT codigo,descripcion FROM carros WHERE activo=1 ORDER BY codigo')->fetchAll();$codigo=trim((string)($_GET['carro']??''));$valid=array_column($carros,'codigo');$target=in_array($codigo,$valid,true)?app_url('ver.php?carro='.rawurlencode($codigo)):'';require_once __DIR__.'/partials/layout.php';layout_start('Generar códigos QR',$user,'qr');?><a class="module-back no-print" href="panel.php">← Volver al escritorio</a><section class="module-card"><h1>Generar código QR</h1><p>Selecciona un carro para crear el acceso directo a su historial.</p><form class="no-print"><label for="carro">Carro</label><select id="carro" name="carro" onchange="this.form.submit()"><option value="">Selecciona un carro</option><?php foreach($carros as $c): ?><option value="<?=e($c['codigo'])?>" <?=$codigo===$c['codigo']?'selected':''?>><?=e($c['codigo'])?><?= $c['descripcion']?' — '.e($c['descripcion']):''?></option><?php endforeach;?></select></form><?php if($target): ?><div id="qrcode" class="qr-preview"></div><p class="module-url"><?=e($target)?></p><div class="module-actions no-print"><button type="button" id="download">Descargar PNG</button><button type="button" onclick="window.print()">Imprimir</button></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>new QRCode(document.getElementById('qrcode'),{text:<?=json_encode($target,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,width:280,height:280,colorDark:'#152f3b',colorLight:'#fff'});document.getElementById('download').onclick=()=>{const c=document.querySelector('#qrcode canvas'),i=document.querySelector('#qrcode img'),d=c?c.toDataURL('image/png'):i?.src;if(!d)return;const a=document.createElement('a');a.href=d;a.download='qr-<?=e($codigo)?>.png';a.click()};</script><?php else: ?><div class="module-alert warn">Selecciona un carro para generar su QR.</div><?php endif;?></section><?php layout_end();
